B=[['拉丁 vulnus，属格 vulneris','伤口'],['拉丁 vulnerare','使受伤']]
W=[
E('vulnerable','/ˈvʌlnərəbəl/','容易受伤的；易受影响的；缺乏保护的','像护甲上露出一块空隙，外面的伤害容易从那里进来。','接晚期拉丁 vulnerabilis，来自 vulnerare；现代用 -able 帮助理解容易受到伤害。',B+[['晚期拉丁 vulnerabilis → 英语 vulnerable','伤害相关的 → 容易受伤、受攻击的']],'vulnerable to criticism 是容易被批评伤到；vulnerable to attack 是容易受到攻击。说一个人愿意 show a vulnerable side，也可以是在说他愿意坦露不安、信任别人，不是在骂他软弱。','vulnerable to something；feel vulnerable；vulnerable people；a vulnerable point。','vulnerable 说容易受害或缺乏保护，不等于已经受伤。weak 说力量弱；强大的人在某个处境中也会 vulnerable。',('The exposed cables were vulnerable to damage.','裸露的电缆很容易受损。'),('She felt vulnerable after sharing such a personal story.','讲完那么私人的经历后，她觉得自己像没了保护。'),sources=['https://www.etymonline.com/word/vulnerable','https://en.wiktionary.org/wiki/vulnerable']),
E('vulnerability','/ˌvʌlnərəˈbɪləti/','易受伤害性；脆弱处；漏洞','把护甲上的缺口单独指出来：哪里容易受伤，或者有多容易受伤。','vulnerable + -ity；-able 变为 -ability 形式，重音落在后部。',B+[['vulnerable → vulnerability','容易受伤的 → 易受伤害的状态或弱点']],'emotional vulnerability 是情感上容易受伤、愿意显露真实感受的状态；a security vulnerability 是系统中可被利用的薄弱处。复数 vulnerabilities 常指具体漏洞或弱点。','a security vulnerability；emotional vulnerability；identify vulnerabilities；reduce vulnerability。','vulnerability 是弱点或易受害状态，attack 是攻击行为。发现漏洞不等于已经有人成功利用它。',('The update fixed a security vulnerability in the software.','这次更新修复了软件中的一个安全漏洞。'),('The interview revealed a vulnerability that his public image rarely showed.','这次访谈让人看到了他公众形象中很少显露的脆弱一面。'),sources=['https://www.etymonline.com/word/vulnerability','https://en.wiktionary.org/wiki/vulnerability']),
E('invulnerable','/ɪnˈvʌlnərəbəl/','无法伤害的；不易被击败的','想象护甲严密得没有可乘之隙，攻击打过来也伤不到。','来自拉丁 invulnerabilis，也有法语借入说明；拉丁 in- 不 + vulnerabilis。英语出现早于 vulnerable，不能把它画成后者先造出再加前缀。',B+[['拉丁 in- + vulnerabilis → invulnerabilis','不能被伤害的'],['拉丁／法语 → 英语 invulnerable','不受伤害、难以攻破的']],'feel invulnerable 是觉得自己什么都扛得住；invulnerable to criticism 是仿佛批评伤不到自己。现实人物这样自认时，文章往往会暗示这种自信过头。','invulnerable to attack；feel invulnerable；an invulnerable position。','invulnerable 侧重伤不到，invincible 侧重打不败。并非两个词在所有语境都完全相同。',('The hero believed the armor made him invulnerable.','英雄相信那副盔甲让他刀枪不入。'),('No organization is invulnerable to criticism.','没有哪个组织完全不受批评影响。'),sources=['https://www.etymonline.com/word/invulnerable','https://www.oxfordlearnersdictionaries.com/definition/english/invulnerable','https://en.wiktionary.org/wiki/invulnerable']),
E('invulnerability','/ɪnˌvʌlnərəˈbɪləti/','不受伤害的状态；坚不可摧的感觉','说的不是某一件护甲，而是“我不会受伤、不会被击垮”这种状态或信念。','可分析为 invulnerable + -ity；词典亦联系法语 invulnérabilité，同属拉丁 invulnerabilis 词族。',B+[['拉丁 invulnerabilis → 英语 invulnerable／法语 invulnérabilité','不能被伤害的；不受伤害性'],['英语 invulnerability','不受伤害的状态或感觉']],'a sense of invulnerability 是一种无所畏惧、觉得自己不会受伤的感觉。它可能是故事人物的真实能力，也可能只是现实人物的错觉，需看语境。','a sense of invulnerability；an illusion of invulnerability；lose one’s invulnerability。','confidence 是自信，invulnerability 是不受伤害；把两者等同容易错过作者在说“自信到以为无敌”的语气。',('The victory gave the team a dangerous sense of invulnerability.','这场胜利让队伍产生了危险的无敌感。'),('The story gradually dismantles the hero’s illusion of invulnerability.','故事逐步打破了主人公不会受伤的幻想。'),sources=['https://www.etymonline.com/word/invulnerability','https://en.wiktionary.org/wiki/invulnerability','https://www.collinsdictionary.com/dictionary/english/invulnerability'])]
ROOT=dict(id='C1662',meaning='伤口；伤害',core='VULNER = WOUND',image='想象护甲上的一个缺口：有缺口就容易受伤；把缺口封住，便产生“不受伤害”的想象。',intro='来自拉丁 vulnus，属格 vulneris；vulnerare 表示伤害。词族从身体伤口延伸到情绪、组织和系统的薄弱处，词根的本质是伤害能否进入。',forms='vulner- 保留在四个核心词中。-able 形容容易受伤，-ability 把这种状态名词化；in- 在这里是否定。invulnerable 有独立拉丁借入链，不能把现代拆解当成英语出现顺序。',branches=[['容易受伤或受到攻击','vulnerable, vulnerability'],['无法伤害或自以为无敌','invulnerable, invulnerability']],contrasts='vulnerable 不等于 weak，也不等于已经 wounded；vulnerability 可以是具体安全漏洞。invulnerable 是伤不到，invincible 是打不败。',practice='Admitting vulnerability does not make a person weak, and confidence does not make anyone invulnerable.\n\n承认自己有脆弱之处不代表软弱，自信也不会让任何人变得刀枪不入。',words=[x['word'] for x in W],exclude={})
